#[serde(tag = "_variant")]
pub enum SystemdSliceCgroupPath {
    SliceCgroupPath {
        path: NonEmptyStr,
    },
    SliceNameNotASlice {
        spelling: String,
    },
}

pub fn systemd_slice_suffix() -> String {
    thread_local! {
        static CACHED: String = {
            ".slice".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn systemd_root_slice_name() -> String {
    thread_local! {
        static CACHED: String = {
            "-.slice".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn systemd_slice_ancestor_names(stem: String) -> Rc<Vec<String>> {
    Rc::new(stem.clone().split(&"-".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<String>>, segment: String| match acc.clone().last().cloned() {
    std::option::Option::None => Rc::new(vec![segment.clone()]),
    Some(prev) => v1_rt::concat(acc.clone(), Rc::new(vec![Rc::new(vec![prev.clone(), "-".to_string(), segment.clone()]).join(&"".to_string())])),
})
}

pub fn systemd_slice_cgroup_path(mount_point: String, slice: String) -> Rc<SystemdSliceCgroupPath> {
    {
        let name = slice.clone();
if (name.clone() == systemd_root_slice_name()) {
            Rc::new(SystemdSliceCgroupPath::SliceCgroupPath {
    path: mount_point.clone(),
})
        } else {
            if !v1_rt::ends_with(name.clone(), systemd_slice_suffix()) {
                Rc::new(SystemdSliceCgroupPath::SliceNameNotASlice {
    spelling: name.clone(),
})
            } else {
                {
                    let stem = v1_rt::substring(&name, 0, v1_rt::int_sub(v1_rt::string_length(&name), v1_rt::string_length(&systemd_slice_suffix())));
if (stem.clone() == "".to_string()) {
                        Rc::new(SystemdSliceCgroupPath::SliceNameNotASlice {
    spelling: name.clone(),
})
                    } else {
                        Rc::new(SystemdSliceCgroupPath::SliceCgroupPath {
    path: systemd_slice_ancestor_names(stem.clone()).iter().cloned().fold(mount_point.clone(), |acc: String, ancestor: String| Rc::new(vec![acc, "/".to_string(), ancestor.clone(), systemd_slice_suffix()]).join(&"".to_string())),
})
                    }
}
            }
        }
}
}

