pub struct SystemdUnitName {
    stem: String,
    kind: SystemdUnitKind,
}
impl SystemdUnitName {
    pub fn stem(&self) -> String {
        self.stem.clone()
    }
    pub fn kind(&self) -> SystemdUnitKind {
        self.kind.clone()
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum SystemdUnitNameAdmission {
    SystemdUnitNameAdmitted {
        name: Rc<SystemdUnitName>,
    },
    SystemdUnitNameStemEmpty,
    SystemdUnitNameDisallowedCharacter {
        stem: String,
        character: String,
    },
    SystemdUnitNameOverlong {
        length: i64,
    },
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum SystemdUnitNameCharWalk {
    SystemdUnitNameCharsWalking {
        index: i64,
    },
    SystemdUnitNameCharHit {
        index: i64,
    },
}
impl SystemdUnitNameCharWalk {
    pub fn index(&self) -> i64 {
        match self {
            SystemdUnitNameCharWalk::SystemdUnitNameCharsWalking { index: __val, .. } => __val.clone(),
            SystemdUnitNameCharWalk::SystemdUnitNameCharHit { index: __val, .. } => __val.clone(),
        }
    }
}

pub fn systemd_unit_name_char_admitted(cp: i64) -> bool {
    (((((((((cp.clone() >= 48) && (cp.clone() <= 57)) || ((cp.clone() >= 65) && (cp.clone() <= 90))) || ((cp.clone() >= 97) && (cp.clone() <= 122))) || (cp.clone() == 58)) || (cp.clone() == 95)) || (cp.clone() == 46)) || (cp.clone() == 45)) || (cp.clone() == 92))
}

pub fn systemd_unit_name_first_disallowed(stem: String) -> Option<String> {
    match (*v1_rt::chars(&stem).iter().cloned().fold(Rc::new(SystemdUnitNameCharWalk::SystemdUnitNameCharsWalking {
    index: 0,
}), |acc: Rc<SystemdUnitNameCharWalk>, cp: i64| match (*acc).clone() {
    SystemdUnitNameCharWalk::SystemdUnitNameCharHit { index: i, .. } => Rc::new(SystemdUnitNameCharWalk::SystemdUnitNameCharHit {
    index: i.clone(),
}),
    SystemdUnitNameCharWalk::SystemdUnitNameCharsWalking { index: i, .. } => if systemd_unit_name_char_admitted(cp.clone()) {
        Rc::new(SystemdUnitNameCharWalk::SystemdUnitNameCharsWalking {
    index: v1_rt::int_add(i.clone(), 1),
})
    } else {
        Rc::new(SystemdUnitNameCharWalk::SystemdUnitNameCharHit {
    index: i.clone(),
})
    },
})).clone() {
    SystemdUnitNameCharWalk::SystemdUnitNameCharsWalking { index: _, .. } => std::option::Option::None,
    SystemdUnitNameCharWalk::SystemdUnitNameCharHit { index: i, .. } => Some(v1_rt::substring(&stem, i.clone(), v1_rt::int_add(i.clone(), 1))),
}
}

pub fn systemd_unit_name_wire(name: Rc<SystemdUnitName>) -> String {
    match name.kind() {
    SystemdUnitKind::ServiceUnit => Rc::new(vec![name.stem(), systemd_service_unit_suffix()]).join(&"".to_string()),
}
}

pub fn systemd_service_unit_name(stem: String) -> Rc<SystemdUnitNameAdmission> {
    if (v1_rt::string_length(&stem) == 0) {
        Rc::new(SystemdUnitNameAdmission::SystemdUnitNameStemEmpty)
    } else {
        match systemd_unit_name_first_disallowed(stem.clone()) {
    Some(ch) => Rc::new(SystemdUnitNameAdmission::SystemdUnitNameDisallowedCharacter {
    stem: stem.clone(),
    character: ch.clone(),
}),
    std::option::Option::None => {
            let n = v1_rt::int_add(v1_rt::string_length(&stem), v1_rt::string_length(&systemd_service_unit_suffix()));
if (n.clone() > systemd_unit_name_max_length()) {
                Rc::new(SystemdUnitNameAdmission::SystemdUnitNameOverlong {
    length: n.clone(),
})
            } else {
                Rc::new(SystemdUnitNameAdmission::SystemdUnitNameAdmitted {
    name: Rc::new(SystemdUnitName {
    stem: stem.clone(),
    kind: SystemdUnitKind::ServiceUnit,
}),
})
            }
},
}
    }
}

pub fn systemd_unit_name_refusal_detail(admission: Rc<SystemdUnitNameAdmission>) -> String {
    match (*admission.clone()).clone() {
    SystemdUnitNameAdmission::SystemdUnitNameAdmitted { name: _, .. } => "systemd unit name was admitted".to_string(),
    SystemdUnitNameAdmission::SystemdUnitNameStemEmpty => "systemd unit name stem is empty".to_string(),
    SystemdUnitNameAdmission::SystemdUnitNameDisallowedCharacter { character: ch, .. } => Rc::new(vec!["systemd unit name has a character systemd.unit(5) disallows: ".to_string(), ch.clone()]).join(&"".to_string()),
    SystemdUnitNameAdmission::SystemdUnitNameOverlong { length: n, .. } => Rc::new(vec!["systemd unit name length ".to_string(), (n.clone()).to_string(), " exceeds 255".to_string()]).join(&"".to_string()),
}
}

